    \cref{alg:decrease_triangles} now takes a feasible assignment for \cref{eq:polynomial_to_lower_bound} and produces another feasible assignment with smaller support and attaining a smaller value. The goal is to find a feasible assignment for which we can explicitly compute a lower bound which therefore also lower bounds the original assignment.

    \begin{algorithm}
    \caption{Find a minimal assignment for \cref{eq:polynomial_to_lower_bound}}
    \label{alg:decrease_triangles}
    \begin{algorithmic}
    \REQUIRE $x_{i,d}\in\mathbb N$ with $\sum_{d}x_{i,d} = |V_i|$, loop color $c_\ell$ in $E$, enumeration $i_1,...,i_r$ of $V(E)$.


    \FOR{k=1,\dots,r}
        \STATE $d^*\gets arg\,min_{d\in[c]} \begin{cases} \frac{1}{2}|V_{i_k}|&\text{if $d=c_\ell$} \\ \sum_{E(\{i_k,j\})=d} x_{j,d}&\text{otherwise} \end{cases}$
        \FOR{ $d\in [c]$}
            \IF{ $d \ne d^*$}
                \STATE $x_{i_k,d} \gets 0$
            \ELSE
                \STATE $x_{i_k,d} \gets |V_{i_k}|$
                \STATE $\alpha(i_k)=d$
            \ENDIF
        \ENDFOR
    \ENDFOR
    \RETURN $\alpha$
    \end{algorithmic}
    \end{algorithm}

